def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 2 or no_water >= 2:
            return float(min(budget, 20.0))
        return float(min(budget, 5.0))

    total_players = 1 + len(alive_opponents)
    expected_demand = WATER_REQ * total_players
    slack = supply - expected_demand

    prev_bids = []
    max_prev_bid = 0.0
    eric_like_pressure = 0.0
    desperate_count = 0
    rich_alive = 0

    for opp in alive_opponents:
        if opp.get('budget', 0) >= 100:
            rich_alive += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            bid = float(bid)
            prev_bids.append(bid)
            if bid > max_prev_bid:
                max_prev_bid = bid
            if bid >= 120:
                eric_like_pressure = max(eric_like_pressure, bid)

    emergency = (hp <= 2) or (no_water >= 2)
    pressured = (hp <= 4) or (no_water >= 1)
    tight_supply = supply <= 18
    medium_tight = supply <= 21

    if emergency:
        if eric_like_pressure > 0:
            bid = min(budget, eric_like_pressure + 1.0)
        else:
            bid = min(budget, max(60.0, DAILY_SALARY * 0.95))
        return float(max(0.0, bid))

    if tight_supply:
        if eric_like_pressure > 0 and hp >= 6 and no_water == 0:
            bid = min(budget, 18.0)
        else:
            base = 42.0
            if max_prev_bid > 0:
                base = max(base, min(85.0, max_prev_bid + 2.0))
            if desperate_count >= 2:
                base += 8.0
            bid = min(budget, base)
        return float(max(0.0, bid))

    if medium_tight:
        if eric_like_pressure > 0 and hp >= 7 and no_water == 0:
            bid = min(budget, 12.0)
        else:
            base = 24.0 if not pressured else 38.0
            if max_prev_bid > 0 and max_prev_bid < 100:
                base = max(base, min(55.0, max_prev_bid + 1.5))
            bid = min(budget, base)
        return float(max(0.0, bid))

    if slack >= 0:
        if pressured:
            bid = min(budget, 16.0)
        else:
            bid = min(budget, 6.0)
        if rich_alive >= 1 and eric_like_pressure > 0 and hp >= 7:
            bid = min(budget, 4.0)
        return float(max(0.0, bid))

    base = 18.0 if not pressured else 30.0
    if max_prev_bid > 0 and max_prev_bid < 100:
        base = max(base, min(60.0, max_prev_bid + 1.0))
    if eric_like_pressure > 0 and hp >= 7 and no_water == 0:
        base = min(base, 10.0)
    return float(max(0.0, min(budget, base)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_competitors = len(alive_opponents) + 1 # Including myself

    # Calculate available water slots
    supply_slots = int(day_context['supply'] // WATER_REQ)

    # If no opponents, bid low to save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_yesterday_bid = 0
    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)

    my_current_bid = 0.0

    # Strategy 1: Survival is paramount if HP is low or no water days accumulating
    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 1:
        # Critical health, bid very aggressively, just below full salary to leave some buffer
        my_current_bid = DAILY_SALARY - 1 # 139
    elif day_context['day'] >= EPISODE_DAYS - 2: # Late game, be more aggressive
        my_current_bid = DAILY_SALARY * 0.8
    else:
        # Normal health, consider competition and supply
        if num_alive_competitors > supply_slots:
            # High competition, bid aggressively
            if max_yesterday_bid > DAILY_SALARY * 0.7: # If opponents are already bidding high (e.g., Alex)
                my_current_bid = max_yesterday_bid + 5
            else:
                my_current_bid = DAILY_SALARY * 0.75 # Default high competition bid (105)
        else:
            # Less competition, can be more conservative
            if max_yesterday_bid > 0:
                # Bid slightly above the highest previous bid, but ensure it's not too low
                my_current_bid = max(DAILY_SALARY * 0.4, max_yesterday_bid + 2)
            else:
                my_current_bid = DAILY_SALARY * 0.4 # Default low competition bid (56)

    # Ensure bid is within budget and non-negative
    final_bid = min(my_status['budget'], my_current_bid)
    final_bid = max(final_bid, 0.0) 

    return final_bid
